// ============================================================================
// USB_Type_C_Port_Controller_apb: APB4 register wrapper around USB_Type_C_Port_Controller_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/USB_Type_C_Port_Controller.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/USB_Type_C_Port_Controller.md
// ============================================================================
module USB_Type_C_Port_Controller_apb #(
  parameter int DW = 32,
  parameter int AW = 32
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [1:0] cc1,
  input logic [1:0] cc2,
  output logic attached,
  output logic orientation,
  output logic vbus_en
);
  localparam logic [31:0] ID_VALUE = 32'h54430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [12:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd13) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[6] | hit[7] | hit[8])));   // core registers take whole words

  // ---------------- core ----------------
  logic [7:0]    c_reg_wdata;
  logic [7:0]    c_reg_rdata;
  logic          c_reg_rd;
  logic          c_reg_wr;
  logic          c_irq;
  USB_Type_C_Port_Controller_top #(.DW(DW), .AW(AW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cc1(cc1),
    .cc2(cc2),
    .attached(attached),
    .orientation(orientation),
    .vbus_en(vbus_en),
    .reg_addr((wr ? ((hit[6] ? 3'd1 : 3'd0) | (hit[7] ? 3'd2 : 3'd0) | (hit[8] ? 3'd3 : 3'd0)) : rd ? ((hit[5] ? 3'd0 : 3'd0) | (hit[6] ? 3'd1 : 3'd0) | (hit[7] ? 3'd2 : 3'd0) | (hit[8] ? 3'd3 : 3'd0) | (hit[9] ? 3'd4 : 3'd0) | (hit[10] ? 3'd5 : 3'd0) | (hit[11] ? 3'd6 : 3'd0) | (hit[12] ? 3'd7 : 3'd0)) : 3'd0)),
    .reg_wdata(c_reg_wdata),
    .reg_rdata(c_reg_rdata),
    .reg_rd(c_reg_rd),
    .reg_wr(c_reg_wr),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------
  // CORE: the core's register port (indices on the instance)
  assign c_reg_wr = wr & (PSTRB == 4'hF) & (hit[6] | hit[7] | hit[8]);
  assign c_reg_wdata = PWDATA[7:0];
  assign c_reg_rd = rd & (hit[5] | hit[6] | hit[7] | hit[8] | hit[9] | hit[10] | hit[11] | hit[12]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(c_reg_rdata);
      10'd6: apb_rdata = 32'(c_reg_rdata);
      10'd7: apb_rdata = 32'(c_reg_rdata);
      10'd8: apb_rdata = 32'(c_reg_rdata);
      10'd9: apb_rdata = 32'(c_reg_rdata);
      10'd10: apb_rdata = 32'(c_reg_rdata);
      10'd11: apb_rdata = 32'(c_reg_rdata);
      10'd12: apb_rdata = 32'(c_reg_rdata);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
